/* 基础过渡 */
.box {
  width: 100px;
  height: 100px;
  background: #3498db;
  /* 过渡：宽度变化，0.3秒，ease速度曲线 */
  transition: width 0.3s ease;
}

.box:hover {
  width: 200px; /* 鼠标悬停时宽度变200px，会有0.3秒的平滑过渡 */
}

/* 多属性分别过渡 */
.card {
  background: #fff;
  color: #333;
  transform: scale(1);
  /* 多个属性用逗号分隔 */
  transition: background 0.3s ease, color 0.3s ease, transform 0.3s ease;
}

.card:hover {
  background: #3498db;
  color: #fff;
  transform: scale(1.05);
}

/* all过渡所有属性（简单但性能差，不推荐） */
.btn {
  transition: all 0.3s ease;
}

/* 不同速度曲线对比 */
.linear  { transition: all 0.5s linear; }       /* 匀速 */
.ease    { transition: all 0.5s ease; }         /* 默认 */
.ease-in { transition: all 0.5s ease-in; }      /* 加速 */
.ease-out { transition: all 0.5s ease-out; }    /* 减速 */
.ease-in-out { transition: all 0.5s ease-in-out; } /* 先加速后减速 */

/* cubic-bezier 自定义贝塞尔曲线 */
/* 两个控制点 (x1,y1) (x2,y2)，x必须在0-1之间 */
.bouncy {
  /* 弹性效果：最后会超出一点再回来 */
  transition: transform 0.5s cubic-bezier(0.68, -0.55, 0.27, 1.55);
}
.bouncy:hover {
  transform: scale(1.2);
}

/* 网站推荐：https://cubic-bezier.com/ 可视化调整曲线 */
/* 常用预设：
   easeInOutCubic: cubic-bezier(0.65, 0, 0.35, 1)
   easeOutBack:    cubic-bezier(0.34, 1.56, 0.64, 1)
*/

/* 阶梯式延迟 - 多个元素依次出现 */
.item:nth-child(1) { transition: all 0.3s ease 0s; }
.item:nth-child(2) { transition: all 0.3s ease 0.1s; }
.item:nth-child(3) { transition: all 0.3s ease 0.2s; }
.item:nth-child(4) { transition: all 0.3s ease 0.3s; }

.item {
  opacity: 0;
  transform: translateY(20px);
}
.container:hover .item {
  opacity: 1;
  transform: translateY(0);
}

/* 不同属性不同时长不同延迟 */
.fancy {
  background: #3498db;
  transform: scale(1);
  transition:
    background 0.2s ease 0s,
    transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) 0.1s;
}
.fancy:hover {
  background: #e74c3c;
  transform: scale(1.1);
}

/* translate 平移 */
.box {
  width: 100px;
  height: 100px;
  background: #3498db;
  transition: transform 0.3s ease;
}

/* 向右移动50px，向下移动20px */
.box.move1:hover { transform: translate(50px, 20px); }

/* 只向右移动50px */
.box.move2:hover { transform: translateX(50px); }

/* 只向下移动50px */
.box.move3:hover { transform: translateY(50px); }

/* 居中技巧：配合绝对定位实现元素水平垂直居中 */
.center {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%); /* 往左上移动自身一半 */
}

/* 百分比是相对自身大小的，不是父元素 */
.box:hover { transform: translateX(50%); } /* 移动自身宽度的50% */

/* rotate 旋转 */
.icon {
  transition: transform 0.3s ease;
}

/* 顺时针旋转45度 */
.icon.r1:hover { transform: rotate(45deg); }

/* 顺时针旋转180度 */
.icon.r2:hover { transform: rotate(180deg); }

/* 逆时针旋转90度 */
.icon.r3:hover { transform: rotate(-90deg); }

/* 持续旋转（用关键帧动画，下章学） */
.spinner {
  animation: spin 2s linear infinite;
}
@keyframes spin {
  to { transform: rotate(360deg); }
}

/* 单位除了deg还有：turn（圈）、rad（弧度） */
/* 1turn = 360deg, 2rad ≈ 114.6deg */
.half-turn:hover { transform: rotate(0.5turn); } /* 旋转半圈 */

/* scale 缩放 */
.card {
  transition: transform 0.3s ease;
}

/* 放大到1.5倍 */
.card.s1:hover { transform: scale(1.5); }

/* 缩小到0.5倍 */
.card.s2:hover { transform: scale(0.5); }

/* 水平放大2倍，垂直不变 */
.card.s3:hover { transform: scaleX(2); }

/* 垂直放大2倍 */
.card.s4:hover { transform: scaleY(2); }

/* 分别指定水平和垂直缩放 */
.card.s5:hover { transform: scale(1.2, 0.8); }

/* 镜像翻转（负值） */
.flip-x:hover { transform: scaleX(-1); } /* 水平镜像 */
.flip-y:hover { transform: scaleY(-1); } /* 垂直镜像 */

/* 注意：scale会让文字也缩放，可能模糊 */

/* skew 斜切 */
.parallel {
  width: 200px;
  height: 60px;
  background: #e74c3c;
  /* X轴倾斜20度，做成平行四边形 */
  transform: skewX(-20deg);
}

/* 组合变换：多个变换写在一起，用空格分隔 */
.combo {
  transition: transform 0.4s ease;
}
.combo:hover {
  /* 顺序很重要！先平移再旋转，和先旋转再平移，效果不同 */
  transform: translate(50px, 0) rotate(45deg) scale(1.2);
}

/* 斜切按钮（背景斜切，文字不斜） */
.skew-btn {
  position: relative;
  padding: 12px 32px;
  border: none;
  background: transparent;
  color: #fff;
  cursor: pointer;
}
.skew-btn::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0; bottom: 0;
  background: #3498db;
  transform: skewX(-20deg);
  z-index: -1;
}

/* 默认中心旋转 */
.spin-center {
  transform-origin: center center; /* 等同于 50% 50% */
  transition: transform 0.5s ease;
}
.spin-center:hover { transform: rotate(180deg); }

/* 左上角为原点旋转 */
.spin-tl {
  transform-origin: top left; /* 0% 0% */
  transition: transform 0.5s ease;
}
.spin-tl:hover { transform: rotate(180deg); }

/* 右下角为原点缩放 */
.scale-br {
  transform-origin: bottom right;
  transition: transform 0.5s ease;
}
.scale-br:hover { transform: scale(1.5); }

/* 摆动效果（用关键帧，原点在顶部中间） */
.swing {
  transform-origin: top center;
  animation: swing 2s ease-in-out infinite;
}
@keyframes swing {
  0%, 100% { transform: rotate(-15deg); }
  50% { transform: rotate(15deg); }
}

/* 卡片悬浮效果 */
.hover-card {
  transition: transform 0.3s ease, box-shadow 0.3s ease;
  box-shadow: 0 2px 8px rgba(0,0,0,0.1);
}
.hover-card:hover {
  transform: translateY(-8px); /* 上移8px */
  box-shadow: 0 12px 24px rgba(0,0,0,0.15);
}

/* 图片放大遮罩 */
.zoom-img {
  overflow: hidden;
}
.zoom-img img {
  transition: transform 0.5s ease;
}
.zoom-img:hover img {
  transform: scale(1.1);
}

/* 按钮按压效果 */
.press-btn {
  transition: transform 0.1s ease;
}
.press-btn:active {
  transform: scale(0.95); /* 按下时缩小 */
}

/* 翻转箭头（下拉菜单用） */
.arrow {
  transition: transform 0.3s ease;
}
.dropdown.open .arrow {
  transform: rotate(180deg);
}

