/* 定义一个变色动画 */
@keyframes colorChange {
  0%   { background: red; }
  50%  { background: yellow; }
  100% { background: green; }
}

/* 定义一个弹跳动画 */
@keyframes bounce {
  0%, 100% { transform: translateY(0); }    /* 起始和结束在原位 */
  50%      { transform: translateY(-50px); } /* 中间向上跳50px */
}

/* 用from和to简写（只有两个状态时） */
@keyframes fadeIn {
  from { opacity: 0; }    /* 透明 */
  to   { opacity: 1; }    /* 不透明 */
}

/* 应用动画 */
.box {
  width: 100px;
  height: 100px;
  animation: colorChange 3s ease infinite;
  /* 动画名 时长 速度曲线 播放次数 */
}

/* 完整的animation写法 */
.box {
  /* name duration timing delay count direction fill play-state */
  animation: bounce 2s ease 0s infinite alternate both running;
}

/* 拆开写 */
.box2 {
  animation-name: bounce;
  animation-duration: 2s;
  animation-timing-function: ease;
  animation-delay: 0s;
  animation-iteration-count: infinite; /* 无限循环 */
  animation-direction: alternate;       /* 来回播放 */
  animation-fill-mode: both;            /* 前后都保持动画状态 */
  animation-play-state: running;        /* 播放中 */
}

/* animation-direction取值：
   normal    - 每次都正向播放
   reverse   - 每次都反向播放
   alternate - 正向一次，反向一次，交替
   alternate-reverse - 反向开始，交替
*/

/* animation-fill-mode取值：
   none      - 默认，动画前后恢复原样
   forwards  - 动画结束后保持最后一帧
   backwards - 动画开始前保持第一帧（配合delay用）
   both      - 前后都保持
*/

/* loading旋转 */
.loader {
  width: 40px;
  height: 40px;
  border: 4px solid #f3f3f3;
  border-top: 4px solid #3498db;
  border-radius: 50%;
  animation: spin 1s linear infinite; /* 匀速无限循环 */
}
@keyframes spin {
  to { transform: rotate(360deg); }
}

/* 呼吸效果 */
.breath {
  animation: breath 2s ease-in-out infinite;
}
@keyframes breath {
  0%, 100% { transform: scale(1); opacity: 0.8; }
  50%      { transform: scale(1.1); opacity: 1; }
}

/* 摆动效果 */
.swing {
  transform-origin: top center;
  animation: swing 2s ease-in-out infinite;
}
@keyframes swing {
  0%, 100% { transform: rotate(-15deg); }
  50%      { transform: rotate(15deg); }
}

/* 闪烁 */
.blink {
  animation: blink 1.5s ease infinite;
}
@keyframes blink {
  0%, 100% { opacity: 1; }
  50%      { opacity: 0.3; }
}

/* 多动画组合：边旋转边变色 */
.rainbow-spin {
  width: 100px;
  height: 100px;
  border-radius: 50%;
  animation:
    spin 2s linear infinite,
    colorChange 4s linear infinite;
}
@keyframes spin {
  to { transform: rotate(360deg); }
}
@keyframes colorChange {
  0%   { background: #e74c3c; }
  33%  { background: #f1c40f; }
  66%  { background: #2ecc71; }
  100% { background: #e74c3c; }
}

/* 入场动画（页面加载时元素淡入上滑） */
.fade-up {
  opacity: 0;
  animation: fadeUp 0.8s ease forwards;
}
@keyframes fadeUp {
  from {
    opacity: 0;
    transform: translateY(30px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* 阶梯式入场（多个元素依次出现） */
.item1 { animation: fadeUp 0.8s ease 0.1s both; }
.item2 { animation: fadeUp 0.8s ease 0.3s both; }
.item3 { animation: fadeUp 0.8s ease 0.5s both; }
.item4 { animation: fadeUp 0.8s ease 0.7s both; }

/* 鼠标悬停暂停 */
.pause-hover {
  animation: spin 2s linear infinite;
}
.pause-hover:hover {
  animation-play-state: paused; /* 悬停暂停 */
}

/* 鼠标悬停开始 */
.play-hover {
  /* 初始不播放 */
}
.play-hover:hover {
  animation: wiggle 0.5s ease;
}
@keyframes wiggle {
  0%, 100% { transform: rotate(0); }
  25%      { transform: rotate(-10deg); }
  75%      { transform: rotate(10deg); }
}

/* 弹性入场 */
.drop-in {
  animation: dropIn 0.6s cubic-bezier(0.34, 1.56, 0.64, 1) both;
}
@keyframes dropIn {
  from {
    opacity: 0;
    transform: translateY(-100px) scale(0.5);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

:root {
  /* 在:root定义全局变量，所有元素都能用 */
  --primary-color: #3498db;
  --secondary-color: #2ecc71;
  --text-color: #333;
  --bg-color: #fff;
  --spacing: 16px;
  --border-radius: 8px;
  --font-size: 14px;
}

.button {
  /* 使用变量：var(--变量名) */
  background: var(--primary-color);
  color: #fff;
  padding: var(--spacing);
  border-radius: var(--border-radius);
  font-size: var(--font-size);
}

.card {
  background: var(--bg-color);
  color: var(--text-color);
  padding: var(--spacing);
  border-radius: var(--border-radius);
  border: 2px solid var(--primary-color);
}

/* var()可以带默认值，变量不存在时用默认值 */
.box {
  color: var(--undefined-var, #666); /* 变量不存在，用#666 */
}

:root {
  --color: #3498db; /* 全局变量 */
}

.box {
  color: var(--color); /* 蓝色，用全局变量 */
}

.sidebar {
  --color: #e74c3c; /* 在sidebar定义局部变量，覆盖全局 */
}
.sidebar .box {
  color: var(--color); /* 红色，用的是局部变量 */
}

/* 不同主题区域 */
.theme-dark {
  --bg: #1a1a1a;
  --text: #fff;
}
.theme-light {
  --bg: #fff;
  --text: #333;
}
.theme-dark .content  { background: var(--bg); color: var(--text); }
.theme-light .content { background: var(--bg); color: var(--text); }

/* 局部变量只在定义的子树内有效 */
.special {
  --local: 20px;
  padding: var(--local); /* 有效 */
}
.other {
  padding: var(--local); /* 无效，--local不在作用域内 */
}

:root {
  --spacing: 16px;
  --sidebar-width: 250px;
}

/* calc()基础用法 */
.full-width {
  width: calc(100% - 40px);     /* 宽度减去40px */
  height: calc(100vh - 60px);    /* 视口高度减60px（减去导航栏） */
  padding: calc(var(--spacing) * 2); /* 变量参与计算 */
}

/* 经典布局：侧边栏+主内容 */
.layout {
  display: flex;
}
.sidebar {
  width: var(--sidebar-width);
}
.main {
  /* 主内容宽度 = 100% - 侧边栏宽度 */
  width: calc(100% - var(--sidebar-width));
  padding: var(--spacing);
}

/* 响应式字体 */
.responsive-text {
  /* 字体大小随视口变化 */
  font-size: calc(16px + 2vw); /* 基础16px，每视口宽度增加2vw */
}

/* 三等分（注意除法） */
.third {
  width: calc(100% / 3);
}

/* 居中技巧 */
.center {
  position: absolute;
  left: calc(50% - 100px);  /* 元素宽200px时，向左移100px实现居中 */
  width: 200px;
}

/* 定义浅色主题变量（默认） */
:root {
  --bg-color: #ffffff;
  --text-color: #333333;
  --card-bg: #f5f5f5;
  --border-color: #dddddd;
  --primary: #3498db;
}

/* 深色主题：覆盖变量 */
[data-theme="dark"] {
  --bg-color: #1a1a1a;
  --text-color: #f0f0f0;
  --card-bg: #2a2a2a;
  --border-color: #444444;
  --primary: #5dade2;
}

/* 使用变量 */
body {
  background: var(--bg-color);
  color: var(--text-color);
  transition: background 0.3s ease, color 0.3s ease;
}
.card {
  background: var(--card-bg);
  border: 1px solid var(--border-color);
  padding: 20px;
}

/* 跟随系统深色模式 */
@media (prefers-color-scheme: dark) {
  :root {
    --bg-color: #1a1a1a;
    --text-color: #f0f0f0;
    --card-bg: #2a2a2a;
    --border-color: #444444;
  }
}

/* JS切换：document.documentElement.setAttribute('data-theme', 'dark'); */

/* nth-child 的用法 */

/* 第3个li */
li:nth-child(3) { color: red; }

/* 偶数行（表格斑马纹） */
tr:nth-child(even) { background: #f5f5f5; }
/* 等同于 */
tr:nth-child(2n) { background: #f5f5f5; }

/* 奇数行 */
tr:nth-child(odd) { background: #fff; }
/* 等同于 */
tr:nth-child(2n+1) { background: #fff; }

/* 前3个 */
li:nth-child(-n+3) { color: blue; }

/* 从第3个开始的所有 */
li:nth-child(n+3) { color: green; }

/* 每3个选第1个（每行第一个） */
li:nth-child(3n+1) { background: #eee; }

/* 公式：an+b
   n从0开始递增
   2n+1 = 1,3,5,7... (奇数)
   2n   = 2,4,6,8... (偶数)
   3n+1 = 1,4,7,10...
*/

/* first-child 和 last-child */
li:first-child { font-weight: bold; }
li:last-child { border-bottom: none; }

/* 伪元素：在元素内容前/后插入内容，不占用DOM */

/* 必须有 content 属性，哪怕是空字符串 */
.quote::before {
  content: '"';
  color: #999;
  font-size: 2em;
}
.quote::after {
  content: '"';
  color: #999;
  font-size: 2em;
}

/* 用伪元素做装饰 */
.card::before {
  content: '';
  position: absolute;
  top: 0; left: 0;
  width: 100%;
  height: 4px;
  background: linear-gradient(90deg, #3498db, #e74c3c);
}

/* 清除浮动（经典用法） */
.clearfix::after {
  content: '';
  display: block;
  clear: both;
}

/* 用伪元素做下划线动画 */
.link {
  position: relative;
  text-decoration: none;
}
.link::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 0;
  height: 2px;
  background: #3498db;
  transition: width 0.3s ease;
}
.link:hover::after {
  width: 100%; /* 悬停时下划线展开 */
}

/* ::first-letter 首字母放大 */
p::first-letter {
  font-size: 3em;
  float: left;
  line-height: 1;
}

/* 有type属性的input */
input[type] { border: 1px solid #ccc; }

/* type是text的input */
input[type="text"] { padding: 8px; }

/* type是password的input */
input[type="password"] { letter-spacing: 2px; }

/* 必填字段 */
input[required] { border-color: #e74c3c; }

/* 链接以https开头（安全链接） */
a[href^="https"] { color: green; }

/* 链接以.pdf结尾 */
a[href$=".pdf"]::after {
  content: ' 📄';
}

/* 链接包含某域名 */
a[href*="github"] { color: #333; }

/* class列表包含某个值 */
div[class~="box"] { padding: 20px; }

/* 按钮disabled状态 */
button[disabled] { opacity: 0.5; cursor: not-allowed; }

/* 选中带有data-id属性的元素 */
[data-id] { cursor: pointer; }

/* :is() 匹配多个选择器（类似或） */
/* 以前要写 */
h1, h2, h3 { color: #333; }
h1 a, h2 a, h3 a { color: blue; }
/* 现在用 :is() */
:is(h1, h2, h3) { color: #333; }
:is(h1, h2, h3) a { color: blue; }

/* :not() 排除某些元素 */
/* 所有li，除了第一个 */
li:not(:first-child) { margin-top: 10px; }
/* 所有button，除了disabled */
button:not([disabled]) { cursor: pointer; }
/* 所有input，除了submit类型 */
input:not([type="submit"]):not([type="button"]) {
  padding: 8px;
}

/* :has() 选择包含某子元素的父元素（父选择器，2023+新特性） */
/* 包含img的div */
div:has(img) { padding: 10px; }
/* 包含.active的直接子元素的ul */
ul:has(> .active) { background: #f5f5f5; }
/* 没有p的section */
section:not(:has(p)) { display: none; }
/* 卡片里有图片时改变样式 */
.card:has(.card-image) { padding: 0; }

/* 组合使用 */
:is(.btn, .link):not([disabled]):hover {
  opacity: 0.8;
}

/* 表单验证状态样式 */
input:required { border-left: 3px solid #e74c3c; }
input:optional { border-left: 3px solid #ccc; }
input:valid { border-color: #2ecc71; }
input:invalid { border-color: #e74c3c; }

/* 复选框选中时关联样式 */
input[type="checkbox"]:checked + label {
  color: #2ecc71;
  font-weight: bold;
}

/* 空元素隐藏 */
div:empty { display: none; }

/* focus-within: 输入框或其父元素获焦时高亮 */
.input-group:focus-within {
  border-color: #3498db;
  box-shadow: 0 0 0 3px rgba(52,152,219,0.1);
}

/* 表格斑马纹 + hover */
table tbody tr:nth-child(odd) { background: #f9f9f9; }
table tbody tr:hover { background: #e8f4fc; }

/* 导航栏第一项不要左边距 */
.nav li:not(:first-child) { margin-left: 20px; }

/* 文章段落间距，最后一段不要下边距 */
.article p { margin-bottom: 1em; }
.article p:last-child { margin-bottom: 0; }

/* 外部链接加图标 */
a[href^="http"]:not([href*="mysite.com"])::after {
  content: ' ↗';
  color: #999;
}

/* 基础线性渐变 */
.g1 {
  background: linear-gradient(to right, #3498db, #e74c3c);
}

/* 指定角度 */
.g2 {
  background: linear-gradient(45deg, #3498db, #e74c3c);
}

/* 多色渐变 */
.g3 {
  background: linear-gradient(to right, red, yellow, green, blue);
}

/* 指定颜色位置 */
.g4 {
  background: linear-gradient(to right, red 0%, yellow 50%, green 100%);
}

/* 渐变文字 */
.gradient-text {
  background: linear-gradient(45deg, #3498db, #e74c3c);
  -webkit-background-clip: text; /* 文字作为裁剪区域 */
  background-clip: text;
  color: transparent; /* 文字本身透明，露出背景 */
}

/* 渐变按钮 */
.gradient-btn {
  background: linear-gradient(135deg, #667eea, #764ba2);
  color: #fff;
  border: none;
  padding: 12px 24px;
  border-radius: 6px;
}

/* 重复渐变 */
.stripes {
  background: repeating-linear-gradient(
    45deg,
    #3498db 0px,
    #3498db 10px,
    #fff 10px,
    #fff 20px
  ); /* 斜条纹 */
}

/* radial-gradient 径向渐变（从中心向外） */

/* 默认从中心向外圆形渐变 */
.r1 {
  background: radial-gradient(#3498db, #e74c3c);
}

/* 指定形状和大小 */
.r2 {
  background: radial-gradient(circle at top, #3498db, #e74c3c);
}

/* 椭圆渐变 */
.r3 {
  background: radial-gradient(ellipse, #3498db, #e74c3c);
}

/* 指定圆心位置和大小 */
.r4 {
  background: radial-gradient(circle at 30% 30%, #3498db, #e74c3c);
}

/* 多色径向渐变 */
.r5 {
  background: radial-gradient(circle, #fff 0%, #3498db 50%, #2c3e50 100%);
}

/* 做一个光晕效果 */
.glow {
  background: radial-gradient(
    circle,
    rgba(52,152,219,0.6) 0%,
    rgba(52,152,219,0) 70%
  );
}

/* 圆形头像（配合border-radius） */
.avatar {
  width: 100px;
  height: 100px;
  border-radius: 50%;
  background: radial-gradient(circle at 30% 30%, #fff, #3498db);
}

/* conic-gradient 锥形渐变 */

/* 基础锥形渐变（色轮效果） */
.c1 {
  background: conic-gradient(red, yellow, green, blue, red);
  border-radius: 50%; /* 配合圆形做色轮 */
}

/* 指定起始角度和中心点 */
.c2 {
  background: conic-gradient(from 0deg at 50% 50%, red, yellow, green, blue, red);
}

/* 饼图效果 */
.pie {
  background: conic-gradient(
    #e74c3c 0% 30%,    /* 红色占30% */
    #3498db 30% 70%,   /* 蓝色占40%（从30%到70%）*/
    #2ecc71 70% 100%   /* 绿色占30% */
  );
  border-radius: 50%;
}

/* 旋转加载动画 */
.conic-loader {
  border-radius: 50%;
  background: conic-gradient(#3498db 0deg, transparent 360deg);
  animation: spin 1s linear infinite;
}
@keyframes spin {
  to { transform: rotate(360deg); }
}

/* 棋盘格背景 */
.checker {
  background:
    conic-gradient(#000 25%, #fff 0 50%, #000 0 75%, #fff 0);
  background-size: 50px 50px;
}

/* 单个滤镜 */
.blur { filter: blur(5px); }              /* 模糊5px */
.bright { filter: brightness(1.5); }     /* 变亮1.5倍 */
.dark { filter: brightness(0.5); }       /* 变暗 */
.gray { filter: grayscale(100%); }       /* 全灰 */
.sepia { filter: sepia(100%); }          /* 复古棕褐 */
.invert { filter: invert(100%); }        /* 反色 */
.hue { filter: hue-rotate(90deg); }      /* 色相旋转90度 */

/* 多个滤镜叠加 */
.combo {
  filter: grayscale(50%) brightness(1.2) contrast(1.1);
}

/* hover时变彩色（默认灰，悬停彩色） */
.img-card img {
  filter: grayscale(100%);
  transition: filter 0.5s ease;
}
.img-card:hover img {
  filter: grayscale(0%);
}

/* drop-shadow 跟随形状的阴影（透明PNG也能正确阴影） */
.logo {
  filter: drop-shadow(0 4px 8px rgba(0,0,0,0.3));
}

/* 毛玻璃前的模糊背景 */
.bg-blur {
  filter: blur(20px) brightness(0.7);
}

/* 渐变+滤镜综合：炫光卡片 */
.aurora-card {
  background: linear-gradient(135deg, #667eea, #764ba2, #f093fb);
  background-size: 200% 200%;
  animation: aurora 5s ease infinite;
  color: #fff;
  padding: 40px;
  border-radius: 20px;
}
@keyframes aurora {
  0%, 100% { background-position: 0% 50%; }
  50%      { background-position: 100% 50%; }
}

/* 图片hover滤镜动画 */
.gallery-item {
  overflow: hidden;
}
.gallery-item img {
  filter: grayscale(80%) contrast(1.1);
  transition: filter 0.5s ease, transform 0.5s ease;
}
.gallery-item:hover img {
  filter: grayscale(0%) contrast(1);
  transform: scale(1.05);
}

/* 玻璃拟态按钮 */
.glass-btn {
  background: rgba(255,255,255,0.1);
  backdrop-filter: blur(10px);
  border: 1px solid rgba(255,255,255,0.2);
  color: #fff;
  padding: 12px 32px;
  border-radius: 30px;
  transition: all 0.3s ease;
}
.glass-btn:hover {
  background: rgba(255,255,255,0.2);
  transform: translateY(-2px);
}

/* 父元素设置透视 */
.scene {
  perspective: 1000px;
}

/* 3D旋转 */
.box {
  width: 150px;
  height: 150px;
  background: #3498db;
  transition: transform 0.5s ease;
}

/* rotateX 绕X轴旋转（前后翻转） */
.box.x:hover { transform: rotateX(45deg); }

/* rotateY 绕Y轴旋转（左右翻转） */
.box.y:hover { transform: rotateY(45deg); }

/* rotateZ 绕Z轴旋转（就是2D的rotate） */
.box.z:hover { transform: rotateZ(45deg); }

/* 组合3D旋转 */
.box.combo:hover {
  transform: rotateX(30deg) rotateY(45deg);
}

/* 没有perspective时，3D旋转看起来还是2D的 */
/* 所以3D变换必须配合perspective！ */
.no-perspective {
  transform: rotateY(45deg); /* 看起来就是变窄了，没有3D感 */
}

.scene {
  perspective: 800px;
}

.card {
  width: 200px;
  height: 200px;
  background: linear-gradient(45deg, #3498db, #e74c3c);
  transition: transform 0.5s ease;
  margin: 50px auto;
}

/* 朝观察者移动（变大） */
.card.z-out:hover {
  transform: translateZ(100px);
}

/* 远离观察者（变小） */
.card.z-in:hover {
  transform: translateZ(-100px);
}

/* 3D平移+旋转 */
.card.fly:hover {
  transform: translateZ(150px) rotateY(180deg);
}

/* scale3d 三维缩放 */
.card.scale3d:hover {
  transform: scale3d(1.2, 1.2, 1.2);
}

/* 3D组合：做出卡片悬浮立体效果 */
.card.tilt {
  transform-style: preserve-3d;
}
.card.tilt:hover {
  transform: rotateX(15deg) rotateY(-15deg) translateZ(30px);
}

/* 立体悬浮卡片（常用于产品展示） */
.float-3d {
  animation: float3d 3s ease-in-out infinite;
  transform-style: preserve-3d;
}
@keyframes float3d {
  0%, 100% { transform: translateY(0) rotateY(0); }
  50%      { transform: translateY(-20px) rotateY(10deg); }
}

/* 3D立方体 */
.cube-scene {
  perspective: 1000px;
  width: 200px;
  height: 200px;
  margin: 100px auto;
}
.cube {
  width: 200px;
  height: 200px;
  position: relative;
  transform-style: preserve-3d;
  animation: rotate3d 10s linear infinite;
}
@keyframes rotate3d {
  from { transform: rotateX(0) rotateY(0); }
  to   { transform: rotateX(360deg) rotateY(360deg); }
}

/* 立方体6个面 */
.face {
  position: absolute;
  width: 200px;
  height: 200px;
  border: 2px solid #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 32px;
}
.front  { background: rgba(231,76,60,0.7); transform: translateZ(100px); }
.back   { background: rgba(241,196,15,0.7); transform: rotateY(180deg) translateZ(100px); }
.right  { background: rgba(46,204,113,0.7); transform: rotateY(90deg) translateZ(100px); }
.left   { background: rgba(52,152,219,0.7); transform: rotateY(-90deg) translateZ(100px); }
.top    { background: rgba(155,89,182,0.7); transform: rotateX(90deg) translateZ(100px); }
.bottom { background: rgba(52,73,94,0.7); transform: rotateX(-90deg) translateZ(100px); }

/* translateZ(100px) = 立方体半边长，让面到正确位置 */

/* 鼠标跟随的3D倾斜卡片（JS辅助） */
.tilt-card {
  perspective: 1000px;
}
.tilt-inner {
  transform-style: preserve-3d;
  transition: transform 0.2s ease-out;
  /* JS会动态设置 --rx 和 --ry 变量 */
  transform: rotateX(var(--rx, 0deg)) rotateY(var(--ry, 0deg));
}

/* 卡片上的元素浮起（视差效果） */
.tilt-content {
  transform: translateZ(50px); /* 内容浮起 */
}
.tilt-badge {
  transform: translateZ(80px); /* 徽章浮更高 */
}

