/* 全局变量 */
:root {
  --primary: #667eea;
  --secondary: #764ba2;
  --accent: #f093fb;
  --text: #2d3748;
  --text-light: #718096;
  --bg: #f7fafc;
  --white: #ffffff;
  --spacing-sm: 8px;
  --spacing: 24px;
  --spacing-lg: 64px;
  --radius: 12px;
  --shadow: 0 4px 20px rgba(0,0,0,0.08);
  --shadow-hover: 0 12px 40px rgba(0,0,0,0.15);
  --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

/* 基础重置 */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  color: var(--text);
  background: var(--bg);
  line-height: 1.6;
  overflow-x: hidden;
}

/* 通用入场动画类 */
.fade-in {
  opacity: 0;
  transform: translateY(40px);
  transition: opacity 0.8s ease, transform 0.8s ease;
}
.fade-in.visible {
  opacity: 1;
  transform: translateY(0);
}

/* 渐变文字 */
.gradient-text {
  background: linear-gradient(135deg, var(--primary), var(--secondary));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

// 滚动时触发入场动画
// 用 IntersectionObserver 监听元素是否进入视口

const observer = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      // 进入视口，添加visible类触发动画
      entry.target.classList.add('visible');
      // 动画只播放一次，可选取消监听
      observer.unobserve(entry.target);
    }
  });
}, {
  threshold: 0.15  // 元素15%进入视口就触发
});

// 监听所有需要入场动画的元素
document.querySelectorAll('.feature-card, .fade-in').forEach(el => {
  observer.observe(el);
});

// 数字滚动动画
function animateNumber(element, target, duration = 2000) {
  const start = 0;
  const startTime = performance.now();
  function update(now) {
    const progress = Math.min((now - startTime) / duration, 1);
    const eased = 1 - Math.pow(1 - progress, 3); // easeOutCubic
    element.textContent = Math.floor(start + (target - start) * eased);
    if (progress < 1) {
      requestAnimationFrame(update);
    } else {
      element.textContent = target; // 确保最后是精确值
    }
  }
  requestAnimationFrame(update);
}

// 数字统计区进入视口时触发
const statsObserver = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      document.querySelectorAll('.stat-number').forEach(el => {
        const target = parseInt(el.dataset.target);
        animateNumber(el, target);
      });
      statsObserver.disconnect();
    }
  });
}, { threshold: 0.5 });

statsObserver.observe(document.querySelector('.stats'));

